css:
.rule{position:absolute; top:0; width:1px; z-index:2;
  background:rgba(90,80,200,.45);
  transform-origin:top; transform:scaleY(0);
  transition:transform .8s cubic-bezier(.2,.7,.2,1)}
.is-in .rule{transform:scaleY(1)}
/* 個別指定の例（左位置は等間隔にしない、高さも揃えない） */
.rule:nth-child(1){left:8%;  height:180px; transition-delay:.00s}
.rule:nth-child(2){left:12%; height:300px; transition-delay:.06s}
.rule:nth-child(3){left:21%; height:230px; transition-delay:.12s}
.rule:nth-child(4){left:23%; height:320px; transition-delay:.18s}
/* 1本はパネルの外側（left:101% など）に置く */
